llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "Fevipiprant has an absolute oral bioavailability of 30–40% in humans measured against an intravenous microdose, providing direct human F data above the 20% threshold and the highest Morgan similarity to the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Vixotrigine shows high oral bioavailability in humans with rapid absorption, supporting that a fluorobenzyl-containing heteroaromatic amine can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A related heteroaromatic amine with a fluorinated aryl group showed 23% oral bioavailability in a human IV/oral microdose study, directly supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Pritelivir, a polar heteroaromatic drug, achieved 75% oral bioavailability in humans, demonstrating that high heteroatom content does not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Rufinamide, which shares triazole, fluorobenzyl, and carboxamide/carbamate-like features with the query, has an absolute oral bioavailability of approximately 70–85% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "R406, an aminopyrimidine-containing kinase inhibitor with substantial polar surface area, showed 54.6% absolute oral bioavailability in humans, supporting high F for the query's similar heteroaromatic core.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "All retrieved experimental analogues report oral bioavailability at or above 20%, several with direct human absolute F measurements. Although Morgan similarities are modest, the consistent high-F direction across diverse heteroaromatic drugs—including fluorobenzyl, aminopyrimidine, and triazole-containing structures—supports a high oral bioavailability prediction for the query. The physicochemical prior is mixed but is outweighed by the uniformly supportive experimental evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the query molecule.",
    "All evidence analogues have low Morgan similarity (<0.25), limiting structural transferability.",
    "No retrieved analogue with F < 20% was available to test the low-bioavailability hypothesis.",
    "The query's high TPSA and HBA count were not directly interrogated by permeability or efflux experiments."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

